import java.util.List;
import java.util.ArrayList;
import java.util.Random;

/**
 * Verifies that the new data-driven populate logic is behaviorally identical to
 * the original hardcoded if/else-if block: it consumes the seeded RNG in the same
 * order and produces the same organisms (same species, same cells, same insertion
 * order). Used only to validate the Simulator refactoring; not part of the app.
 */
public class PopulateCheck
{
    private static final int DEPTH = 80;
    private static final int WIDTH = 120;
    private static final double HIPPOPOTAMUS_CREATION_PROBABILITY = 0.01;
    private static final double LEOPARD_CREATION_PROBABILITY = 0.03;
    private static final double BEAR_CREATION_PROBABILITY = 0.03;
    private static final double MONKEY_CREATION_PROBABILITY = 0.08;
    private static final double SLOTH_CREATION_PROBABILITY = 0.08;
    private static final double PLANT_CREATION_PROBABILITY = 0.13;

    // ---- New data-driven model (mirror of what goes into Simulator.java) ----

    @FunctionalInterface
    private interface OrganismFactory {
        Organism create(boolean randomAge, Field field, Location location);
    }

    private static class SpeciesSpawn {
        final double creationProbability;
        final OrganismFactory factory;
        SpeciesSpawn(double creationProbability, OrganismFactory factory) {
            this.creationProbability = creationProbability;
            this.factory = factory;
        }
    }

    private static final List<List<SpeciesSpawn>> SPAWN_GROUPS = List.of(
        List.of(
            new SpeciesSpawn(HIPPOPOTAMUS_CREATION_PROBABILITY, Hippopotamus::new),
            new SpeciesSpawn(LEOPARD_CREATION_PROBABILITY, Leopard::new),
            new SpeciesSpawn(BEAR_CREATION_PROBABILITY, Bear::new),
            new SpeciesSpawn(MONKEY_CREATION_PROBABILITY, Monkey::new)
        ),
        List.of(
            new SpeciesSpawn(SLOTH_CREATION_PROBABILITY, Sloth::new),
            new SpeciesSpawn(PLANT_CREATION_PROBABILITY, Plant::new)
        )
    );

    public static void main(String[] args)
    {
        List<Organism> oldList = new ArrayList<>();
        Randomizer.reset();
        Field oldField = new Field(DEPTH, WIDTH);
        populateOld(oldField, oldList);

        List<Organism> newList = new ArrayList<>();
        Randomizer.reset();
        Field newField = new Field(DEPTH, WIDTH);
        populateNew(newField, newList);

        boolean fieldsMatch = fingerprintField(oldField).equals(fingerprintField(newField));
        boolean listsMatch = fingerprintList(oldList).equals(fingerprintList(newList));
        System.out.println("old organisms: " + oldList.size() + ", new organisms: " + newList.size());
        System.out.println("field grids identical: " + fieldsMatch);
        System.out.println("organism insertion order identical: " + listsMatch);
        System.out.println(fieldsMatch && listsMatch ? "PASS" : "FAIL");
    }

    private static void populateOld(Field field, List<Organism> organisms)
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= HIPPOPOTAMUS_CREATION_PROBABILITY) {
                    organisms.add(new Hippopotamus(true, field, new Location(row, col)));
                }
                else if(rand.nextDouble() <= LEOPARD_CREATION_PROBABILITY) {
                    organisms.add(new Leopard(true, field, new Location(row, col)));
                }
                else if(rand.nextDouble() <= BEAR_CREATION_PROBABILITY) {
                    organisms.add(new Bear(true, field, new Location(row, col)));
                }
                else if(rand.nextDouble() <= MONKEY_CREATION_PROBABILITY) {
                    organisms.add(new Monkey(true, field, new Location(row, col)));
                }
                if(rand.nextDouble() <= SLOTH_CREATION_PROBABILITY) {
                    organisms.add(new Sloth(true, field, new Location(row, col)));
                }
                else if (rand.nextDouble() <= PLANT_CREATION_PROBABILITY) {
                    organisms.add(new Plant(true, field, new Location(row, col)));
                }
            }
        }
    }

    private static void populateNew(Field field, List<Organism> organisms)
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                for (List<SpeciesSpawn> group : SPAWN_GROUPS) {
                    for (SpeciesSpawn spawn : group) {
                        if (rand.nextDouble() <= spawn.creationProbability) {
                            organisms.add(spawn.factory.create(true, field, new Location(row, col)));
                            break;
                        }
                    }
                }
            }
        }
    }

    private static String fingerprintField(Field field)
    {
        StringBuilder sb = new StringBuilder();
        for (int row = 0; row < field.getDepth(); row++) {
            for (int col = 0; col < field.getWidth(); col++) {
                Object o = field.getObjectAt(row, col);
                sb.append(o == null ? '.' : o.getClass().getSimpleName().charAt(0));
            }
        }
        return sb.toString();
    }

    private static String fingerprintList(List<Organism> organisms)
    {
        StringBuilder sb = new StringBuilder();
        for (Organism o : organisms) {
            sb.append(o.getClass().getSimpleName().charAt(0));
        }
        return sb.toString();
    }
}

